# Stage SHARE-S3: โลโก้ RUNGFAR แทนตัว R · ปุ่ม "ติดตามข่าวสาร Facebook" แทน LINE · พื้นหลังแถบบนแยกต่อนายจ้าง
#   พื้นหลัง: employer-share-view (S3) ส่ง employer.banner = ลิงก์รูปชั่วคราว → ใช้แทนสีส้ม (มีเงาให้อ่านตัวหนังสือออก)
import sys

MARK = 'Stage SHARE-S3'
LOGO = 'data:image/png;base64,'
FB_URL = 'https://www.facebook.com/rungfarungfaofficial/'

CSS = """/* Stage SHARE-S3 */
.logo img{width:38px;height:38px;border-radius:50%;background:#fff;padding:2px;box-shadow:0 1px 4px rgba(0,0,0,.18);flex:none}
.hd.has-bg{background-size:cover;background-position:center}
.btn-fb{background:#1877f2;color:#fff;display:inline-flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap}
@media (max-width:420px){.cta a{font-size:13px;padding-left:6px;padding-right:6px;white-space:nowrap}.cta .btn-fb{flex:1.3}.btn-fb svg{width:16px;height:16px}}
.btn-fb svg{width:18px;height:18px;flex:none}
"""

FB_SVG = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M24 12.07C24 5.4 18.63 0 12 0S0 5.4 0 12.07C0 18.1 4.39 23.1 10.13 24v-8.44H7.08v-3.49h3.05V9.41c0-3.02 1.79-4.69 4.53-4.69 1.31 0 2.68.24 2.68.24v2.97h-1.51c-1.49 0-1.96.93-1.96 1.89v2.25h3.33l-.53 3.49h-2.8V24C19.61 23.1 24 18.1 24 12.07z"/></svg>'

BANNER_JS = """  // Stage SHARE-S3: พื้นหลังแถบบนของนายจ้าง (ถ้าตั้งไว้ใน CRM)
  if(d.employer&&d.employer.banner&&/^https:\\/\\//.test(d.employer.banner)){
    const hd=document.querySelector('.hd');
    if(hd){hd.classList.add('has-bg');hd.style.backgroundImage=`linear-gradient(180deg,rgba(20,10,0,.35) 0%,rgba(20,10,0,.62) 100%),url("${String(d.employer.banner).replace(/["\\\\\\n\\r]/g,'')}")`;}
  }
"""


def rep(s, old, new, path):
    n = s.count(old)
    if n != 1:
        sys.exit(f'{path}: anchor count {n} != 1 for: {old[:80]}')
    return s.replace(old, new)


def patch(path):
    s = open(path, encoding='utf-8').read()
    if MARK in s:
        print(path, ': already patched — skip'); return
    s = rep(s, '</style>', CSS + '</style>', path)
    s = rep(s, '<div class="logo"><i>R</i>RUNGFAR</div>', '<div class="logo"><img src="' + LOGO + '" alt="RUNGFAR">RUNGFAR</div>', path)
    s = rep(s, '<a class="btn-line" href="https://line.me/R/ti/p/@rungfarungfa" target="_blank" rel="noopener">แจ้งต่ออายุทาง LINE</a>',
            '<a class="btn-fb" href="' + FB_URL + '" target="_blank" rel="noopener">' + FB_SVG + 'ติดตามข่าวสาร Facebook</a>', path)
    s = rep(s, '  DATA=d;\n', '  DATA=d;\n' + BANNER_JS, path)
    if '<link rel="icon"' not in s:
        s = rep(s, '</title>', '</title>\n<link rel="icon" type="image/png" href="' + LOGO + '">', path)
    open(path, 'w', encoding='utf-8').write(s)
    print(path, ': patched')


for p in sys.argv[1:]:
    patch(p)
